package io.cityoflight.virgo.scala

/** State the invariant first. The point of the type is that the bad value
  * cannot be constructed, not that it is caught later. */
final case class Entry private (id: String, amount: Long)

object Entry:
  /** Refuses rather than throws: the caller has to look at the result. */
  def of(id: String, amount: Long): Either[String, Entry] =
    if id.isEmpty then Left("an entry with no id cannot be reconciled")
    else if amount == 0 then Left("a zero entry is a row that says nothing")
    else Right(Entry(id, amount))

/** The invariant: a ledger sums to zero, or it is not a ledger. */
final class Ledger private (val entries: Vector[Entry]):
  def total: Long = entries.map(_.amount).sum
  def balanced: Boolean = total == 0

  def add(e: Entry): Ledger = Ledger(entries :+ e)

object Ledger:
  val empty: Ledger = Ledger(Vector.empty)
  def apply(es: Vector[Entry]): Ledger = new Ledger(es)
